/* Imagens originais incorporadas: nenhum arquivo PNG externo é necessário. */
:root {
  --north-stars-atlas: url("data:image/png;base64,");
  --north-stars-logo: url("data:image/png;base64,");
}

.artwork {
  background-repeat: no-repeat;
}

.artwork-logo {
  background-image: var(--north-stars-logo);
  background-size: contain;
  background-position: center;
}

/* Janela da ilustração original: compass. */
.artwork-compass {
  background-image: var(--north-stars-atlas);
  background-size: 389.847716% 231.151242%;
  background-position: 14.886165% 11.015491%;
}

/* Janela da ilustração original: plane. */
.artwork-plane {
  background-image: var(--north-stars-atlas);
  background-size: 187.317073% 288.450704%;
  background-position: 92.178771% 25.411061%;
}

/* Janela da ilustração original: globe. */
.artwork-globe {
  background-image: var(--north-stars-atlas);
  background-size: 205.898123% 231.151242%;
  background-position: 6.075949% 89.500861%;
}

/* Janela da ilustração original: ribbons. */
.artwork-ribbons {
  background-image: var(--north-stars-atlas);
  background-size: 240.752351% 299.415205%;
  background-position: 98.552339% 90.175953%;
}

.icon-definitions {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  pointer-events: none;
}